function countryTreasures(key){if(key==='mexico')return mexicoTreasures(key);if(key!=='thailand')return '';return '<section class="thailand-treasures" aria-label="Thailand treasures"><p class="treasures-label treasure-reward-line"><span>TREASURES OF THAILAND — Collect all 3. Earn your profile elephant.</span>'+thailandReward+'</p><div class="treasure-badges">'+thailandTreasureData.map((t,i)=>'<button type="button" class="treasure-badge" data-treasure="'+i+'" aria-label="Discover '+t.name+'" aria-pressed="false">'+thailandTreasureIcons[i]+'<span class="treasure-caption"><strong>'+t.name+'</strong><span>'+t.subtitle+'</span></span></button>').join('')+'</div><div class="treasure-inline-details" hidden role="region" aria-label="Selected treasure details" aria-live="polite"></div></section>';}
